  FROM (VALUES
    ('0232ab35-1b07-5ce4-a92e-0019daaa8463'::uuid, '458fecce-5f40-5ba9-a3f4-87e853f9235f'::uuid, 'Qu’est-ce qu’un objet technique ?', 'mcq', '["Un objet fabriqué par l’humain pour répondre à un besoin","Tout objet naturel","Un objet électrique","Un objet en métal"]'::jsonb, 0, 'Un caillou n’en est pas un, un marteau si.', 1),
    ('87866b93-3272-5503-94fe-265a1191e59c'::uuid, '458fecce-5f40-5ba9-a3f4-87e853f9235f'::uuid, 'À quelle question répond la fonction d’usage ?', 'mcq', '["À quoi ça sert ?","Comment c’est fait ?","Combien ça coûte ?","Qui l’a inventé ?"]'::jsonb, 0, 'Elle s’exprime par un verbe à l’infinitif.', 2),
    ('ca4e2848-f9f8-5e44-bce7-b10d5bad9b51'::uuid, '458fecce-5f40-5ba9-a3f4-87e853f9235f'::uuid, 'Quelle est la fonction d’usage d’un parapluie ?', 'mcq', '["Protéger de la pluie","Être élégant","Coûter peu cher","Se ranger facilement"]'::jsonb, 0, 'Un verbe à l’infinitif + un complément.', 3),
    ('3ae8d6a4-ef33-5ec5-8163-029fdfa1e17b'::uuid, '458fecce-5f40-5ba9-a3f4-87e853f9235f'::uuid, 'Qu’est-ce que la fonction d’estime ?', 'mcq', '["Ce qui fait préférer un objet à un autre rendant le même service","Ce à quoi l’objet sert","Le prix de l’objet","La matière de l’objet"]'::jsonb, 0, 'Couleur, forme, marque.', 4),
    ('74dd810c-83af-54a5-ae5a-636726ded217'::uuid, '458fecce-5f40-5ba9-a3f4-87e853f9235f'::uuid, 'Qu’est-ce qu’un cahier des charges ?', 'mcq', '["La liste des contraintes que l’objet devra respecter","Le mode d’emploi","La facture","Le plan de fabrication"]'::jsonb, 0, 'Il dit ce que l’objet doit faire, pas comment.', 5),
    ('a0b0274f-96da-58cc-b3e0-54f4e8204ac8'::uuid, '458fecce-5f40-5ba9-a3f4-87e853f9235f'::uuid, 'Qu’est-ce qui précède toujours l’objet technique ?', 'mcq', '["Le besoin","Le matériau","Le prix","La marque"]'::jsonb, 0, 'On a inventé le vélo parce qu’on voulait se déplacer.', 6),
    ('0078057b-0356-5793-993b-b21aa1e81c08'::uuid, '458fecce-5f40-5ba9-a3f4-87e853f9235f'::uuid, 'Pourquoi un même besoin peut-il donner des objets différents ?', 'mcq', '["Parce que les utilisateurs sont différents","Parce que les matériaux manquent","Par hasard","Pour augmenter les prix"]'::jsonb, 0, 'Concevoir, c’est d’abord regarder l’utilisateur.', 7),
    ('25ff3172-d567-5c64-92ad-e37fe738a7da'::uuid, '458fecce-5f40-5ba9-a3f4-87e853f9235f'::uuid, 'La fonction d’usage et la fonction d’estime sont la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’une dit à quoi ça sert, l’autre pourquoi on choisit celui-là.', 8),
    ('826ea485-de9f-57f9-99cd-c4caa8e1bd44'::uuid, 'd470fa5a-3d93-5fb3-bc87-6d4a5c411952'::uuid, 'Que dit une fonction technique ?', 'mcq', '["Comment l’objet parvient à rendre son service","À quoi l’objet sert","Combien il coûte","Qui l’utilise"]'::jsonb, 0, 'C’est la tâche d’une partie de l’objet.', 1),
    ('20e28941-b4ce-57e0-a492-3d45b191471a'::uuid, 'd470fa5a-3d93-5fb3-bc87-6d4a5c411952'::uuid, 'Quelle est une fonction technique du vélo ?', 'mcq', '["Transmettre le mouvement","Se déplacer","Être rouge","Coûter 300 euros"]'::jsonb, 0, '« Se déplacer » est la fonction d’usage.', 2),
    ('7a71ec36-af6a-5271-8ca6-bc4855f5805b'::uuid, 'd470fa5a-3d93-5fb3-bc87-6d4a5c411952'::uuid, 'Qu’est-ce qu’une solution technique ?', 'mcq', '["Une façon parmi d’autres de réaliser une fonction technique","Le but de l’objet","Le matériau utilisé","Le prix de vente"]'::jsonb, 0, 'Freiner peut se faire par patins ou par disque.', 3),
    ('76ecd211-e1c2-5e0b-a00e-4647a4668f18'::uuid, 'd470fa5a-3d93-5fb3-bc87-6d4a5c411952'::uuid, 'Sur quoi le concepteur s’appuie-t-il pour choisir une solution ?', 'mcq', '["Le cahier des charges","Son intuition seule","La mode","Le hasard"]'::jsonb, 0, 'Coût, poids, entretien, sécurité.', 4),
    ('319b9574-17e8-5c5e-a9a0-0db4bb6ade03'::uuid, 'd470fa5a-3d93-5fb3-bc87-6d4a5c411952'::uuid, 'Comment représente-t-on l’ensemble des fonctions ?', 'mcq', '["Par un diagramme en arbre","Par une liste alphabétique","Par un graphique circulaire","Par une photo"]'::jsonb, 0, 'Fonction d’usage en haut, fonctions techniques en dessous.', 5),
    ('dff4bf7a-d0a3-573a-afb5-3d40183963ba'::uuid, 'd470fa5a-3d93-5fb3-bc87-6d4a5c411952'::uuid, 'Qu’est-ce qu’un composant ?', 'mcq', '["L’élément concret qui réalise une solution technique","Le besoin de départ","Le cahier des charges","L’utilisateur"]'::jsonb, 0, 'Ressort, engrenage, vis, moteur.', 6),
    ('0d367762-7bb8-5a08-b01f-c0d7fb601207'::uuid, 'd470fa5a-3d93-5fb3-bc87-6d4a5c411952'::uuid, 'Comment comparer deux solutions techniques ?', 'mcq', '["En pesant des critères dans un tableau","En choisissant la moins chère toujours","En prenant la plus récente","Au hasard"]'::jsonb, 0, 'Cela rend le choix explicite.', 7),
    ('7f0aa52f-666c-5b74-bbbd-47f2c9bdaca1'::uuid, 'd470fa5a-3d93-5fb3-bc87-6d4a5c411952'::uuid, 'Une fonction technique n’admet qu’une seule solution possible.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un problème, et il y a toujours plusieurs réponses.', 8),
    ('83b0e0fd-a6a4-5646-98a6-e5488d9c645c'::uuid, '525b9ec3-189a-53e6-9388-35c91cb9b7b9'::uuid, 'Qu’est-ce qui pousse un objet technique à évoluer ?', 'mcq', '["Progrès techniques, besoins, société et économie","Uniquement la mode","Uniquement le prix","Rien, ils ne changent pas"]'::jsonb, 0, 'Plusieurs causes agissent ensemble.', 1),
    ('4a99a990-f279-52f1-8f2e-99efa5166e32'::uuid, '525b9ec3-189a-53e6-9388-35c91cb9b7b9'::uuid, 'Qu’est-ce qui reste souvent identique au fil de l’évolution ?', 'mcq', '["La fonction d’usage","Les solutions techniques","Les matériaux","Le prix"]'::jsonb, 0, 'On a toujours eu besoin de lumière.', 2),
    ('7ff87387-189d-59e8-9d59-43f2816d0db1'::uuid, '525b9ec3-189a-53e6-9388-35c91cb9b7b9'::uuid, 'Quelle est la lignée de l’éclairage ?', 'mcq', '["Feu, bougie, lampe à huile, gaz, incandescence, LED","LED, bougie, feu","Gaz, feu, bougie","Incandescence, feu, LED"]'::jsonb, 0, 'Chaque étape apporte plus de lumière pour moins d’énergie.', 3),
    ('9b6739e7-62fa-58c7-8517-3f4a6960fb61'::uuid, '525b9ec3-189a-53e6-9388-35c91cb9b7b9'::uuid, 'Combien la LED consomme-t-elle par rapport à l’ampoule à filament ?', 'mcq', '["Environ dix fois moins","Autant","Deux fois plus","Cent fois moins"]'::jsonb, 0, 'Pour un éclairage équivalent.', 4),
    ('83e16e4f-20cf-564d-82bc-3bd5c3537e2a'::uuid, '525b9ec3-189a-53e6-9388-35c91cb9b7b9'::uuid, 'Qu’est-ce qu’une famille d’objets techniques ?', 'mcq', '["Des objets remplissant la même fonction d’usage à une même époque","Un objet suivi dans le temps","Des objets du même fabricant","Des objets de même couleur"]'::jsonb, 0, 'La lignée, elle, suit un objet à travers le temps.', 5),
    ('087a36ae-726a-5e04-9973-89e64e16d3cf'::uuid, '525b9ec3-189a-53e6-9388-35c91cb9b7b9'::uuid, 'Qu’est-ce que l’analyse du cycle de vie ?', 'mcq', '["L’étude de l’objet de l’extraction à la fin de vie","La durée de la garantie","Le temps de fabrication","La durée d’utilisation seule"]'::jsonb, 0, 'Elle est devenue un critère de conception.', 6),
    ('afdfc5c6-00d4-5880-80f5-a062bb29abf3'::uuid, '525b9ec3-189a-53e6-9388-35c91cb9b7b9'::uuid, 'Un objet plus récent est-il toujours meilleur ?', 'mcq', '["Non : il peut être plus difficile à réparer ou dépendre de matériaux rares","Oui, toujours","Oui, sauf pour le prix","Cela ne se mesure pas"]'::jsonb, 0, 'Le progrès n’est pas automatique sur tous les critères.', 7),
    ('4f90fde4-b955-5df7-8dfe-dfa8ff18c8d0'::uuid, '525b9ec3-189a-53e6-9388-35c91cb9b7b9'::uuid, 'La fonction d’usage change à chaque évolution technique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce sont les solutions techniques qui changent.', 8),
    ('1de0bcb0-4c64-5960-a9ac-bf3cb44b8302'::uuid, '9e691322-0af0-554a-b855-4349173fee9f'::uuid, 'Quelle famille regroupe le fer, l’aluminium et le cuivre ?', 'mcq', '["Les métaux","Les plastiques","Les céramiques","Les composites"]'::jsonb, 0, 'Résistants et conducteurs.', 1),
    ('4e1c0d21-75dc-5338-8b94-a8dfda4b7453'::uuid, '9e691322-0af0-554a-b855-4349173fee9f'::uuid, 'Quelle est la principale origine des plastiques ?', 'mcq', '["Le pétrole","Le bois","Le sable","Le minerai de fer"]'::jsonb, 0, 'Ils sont longs à se dégrader.', 2),
    ('360af84d-6f4e-5774-9b4a-c731eaa353e0'::uuid, '9e691322-0af0-554a-b855-4349173fee9f'::uuid, 'Qu’est-ce qu’un matériau composite ?', 'mcq', '["Plusieurs matériaux associés pour cumuler leurs qualités","Un métal très pur","Un plastique recyclé","Un matériau naturel"]'::jsonb, 0, 'Béton armé, fibre de carbone, contreplaqué.', 3),
    ('55b2582d-f67f-5d07-bd29-1f9e13314309'::uuid, '9e691322-0af0-554a-b855-4349173fee9f'::uuid, 'Quelle propriété désigne la résistance à la rayure ?', 'mcq', '["La dureté","L’élasticité","La conductivité","La masse volumique"]'::jsonb, 0, 'L’élasticité, c’est reprendre sa forme.', 4),
    ('24e9602f-a0ea-5464-b79c-4fdc1d80947b'::uuid, '9e691322-0af0-554a-b855-4349173fee9f'::uuid, 'Pourquoi le manche d’une casserole est-il en plastique ?', 'mcq', '["Parce que le plastique est isolant thermique","Parce qu’il est plus dur","Parce qu’il coûte plus cher","Parce qu’il conduit la chaleur"]'::jsonb, 0, 'Chaque matériau est choisi pour une raison précise.', 5),
    ('0b6c2721-03d8-510e-90b6-c29432147191'::uuid, '9e691322-0af0-554a-b855-4349173fee9f'::uuid, 'Quels matériaux se recyclent presque indéfiniment ?', 'mcq', '["Le verre et les métaux","Les plastiques","Le bois","Les composites"]'::jsonb, 0, 'Le plastique se dégrade à chaque cycle.', 6),
    ('4be194c3-2296-5a92-8166-e342ab2f47ea'::uuid, '9e691322-0af0-554a-b855-4349173fee9f'::uuid, 'Quelle est la faiblesse des céramiques et des verres ?', 'mcq', '["Ils sont fragiles et cassent net","Ils fondent à basse température","Ils conduisent l’électricité","Ils rouillent"]'::jsonb, 0, 'Ils sont pourtant durs et résistants à la chaleur.', 7),
    ('b8393b24-f1b4-54d2-baea-55d366a680ce'::uuid, '9e691322-0af0-554a-b855-4349173fee9f'::uuid, 'On choisit un matériau parce qu’il est meilleur que les autres.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On le choisit parce que ses propriétés répondent aux contraintes.', 8),
    ('2b000dad-7416-5b4c-99b0-92d08f338f51'::uuid, '885cd9d1-5efb-536a-9b9b-97259bb080a0'::uuid, 'Quelles sont les cinq étapes du cycle de vie d’un objet ?', 'mcq', '["Extraction, fabrication, transport, utilisation, fin de vie","Achat, usage, revente","Conception, vente, recyclage","Fabrication, vente, réparation"]'::jsonb, 0, 'Chacune a un coût environnemental.', 1),
    ('eea5c181-88c1-5c52-9062-d7cb8b0a02e2'::uuid, '885cd9d1-5efb-536a-9b9b-97259bb080a0'::uuid, 'Où se situe l’essentiel de l’impact d’un smartphone ?', 'mcq', '["Dans sa fabrication","Dans son utilisation","Dans son transport","Dans sa fin de vie"]'::jsonb, 0, 'Le garder plus longtemps est donc le meilleur levier.', 2),
    ('2f4cf112-28a6-5b30-8741-860887867af7'::uuid, '885cd9d1-5efb-536a-9b9b-97259bb080a0'::uuid, 'Où se situe l’essentiel de l’impact d’un réfrigérateur ?', 'mcq', '["Dans son utilisation, sur quinze ans","Dans sa fabrication","Dans son transport","Dans son emballage"]'::jsonb, 0, 'C’est l’inverse du smartphone.', 3),
    ('11669c1c-6ba8-566b-89fb-c31532068a79'::uuid, '885cd9d1-5efb-536a-9b9b-97259bb080a0'::uuid, 'Quel est le levier le plus efficace pour réduire l’impact ?', 'mcq', '["Ne pas produire l’objet : s’en passer, le partager, le louer","Le recycler","L’incinérer","Le transporter autrement"]'::jsonb, 0, 'Le recyclage vient loin après.', 4),
    ('d8cc13fb-2aca-50d3-b538-00879e935b70'::uuid, '885cd9d1-5efb-536a-9b9b-97259bb080a0'::uuid, 'Qu’est-ce que l’obsolescence ?', 'mcq', '["Un objet cesse d’être utilisé alors qu’il fonctionne","Un objet qui casse","Un objet recyclé","Un objet neuf"]'::jsonb, 0, 'Pièces indisponibles, logiciel non mis à jour, mode.', 5),
    ('baa510fd-982a-5a37-a275-2ce8dc70917b'::uuid, '885cd9d1-5efb-536a-9b9b-97259bb080a0'::uuid, 'Qu’est-ce que l’indice de réparabilité ?', 'mcq', '["Une note affichée qui informe sur la facilité de réparation","Le prix des pièces","La durée de la garantie","Le poids de l’objet"]'::jsonb, 0, 'Affiché en France depuis 2021.', 6),
    ('3c723641-a5cf-52ae-9dcd-41fa835b1693'::uuid, '885cd9d1-5efb-536a-9b9b-97259bb080a0'::uuid, 'Qu’est-ce que l’écoconception ?', 'mcq', '["Concevoir en pensant à tout le cycle de vie","Fabriquer avec du plastique recyclé seulement","Vendre moins cher","Produire localement uniquement"]'::jsonb, 0, 'Moins de matière, assemblage démontable, pièces disponibles.', 7),
    ('dbdf34b2-64b9-5949-9212-ea99b56cabba'::uuid, '885cd9d1-5efb-536a-9b9b-97259bb080a0'::uuid, 'Recycler un objet est le meilleur moyen de réduire son impact.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Allonger sa durée de vie et ne pas le produire sont plus efficaces.', 8),
    ('32db53e1-bee4-5b96-8592-03d342738283'::uuid, '911b57de-8e67-5047-a151-80255d6dd5ca'::uuid, 'Qu’est-ce qu’un croquis ?', 'mcq', '["Un dessin à main levée qui montre une idée","Un dessin précis et coté","Un dessin avec des symboles normalisés","Une photographie"]'::jsonb, 0, 'Pas d’échelle exacte.', 1),
    ('4155c25f-1faa-54a4-bcc5-c34fc535e3a5'::uuid, '911b57de-8e67-5047-a151-80255d6dd5ca'::uuid, 'Que montre un schéma ?', 'mcq', '["Le fonctionnement ou les liaisons, avec des symboles","L’apparence exacte de l’objet","Les dimensions réelles","La couleur de l’objet"]'::jsonb, 0, 'Il ne ressemble pas à l’objet.', 2),
    ('9e137e05-0668-5d90-a695-50d81e8d5297'::uuid, '911b57de-8e67-5047-a151-80255d6dd5ca'::uuid, 'À quoi sert un plan technique ?', 'mcq', '["À fabriquer l’objet : il est à l’échelle et coté","À montrer une idée","À décorer","À vendre l’objet"]'::jsonb, 0, 'C’est le dessin le plus précis.', 3),
    ('cd4a6126-2b69-5c9f-8217-6a8d78c57b5f'::uuid, '911b57de-8e67-5047-a151-80255d6dd5ca'::uuid, 'Que signifie l’échelle 1:10 ?', 'mcq', '["Le dessin est 10 fois plus petit que le réel","Le dessin est 10 fois plus grand","Le dessin est à taille réelle","L’objet mesure 10 cm"]'::jsonb, 0, '10:1 serait l’inverse.', 4),
    ('8b9fa705-ad02-5a06-9bbc-5eac4fe62b83'::uuid, '911b57de-8e67-5047-a151-80255d6dd5ca'::uuid, 'Quelles sont les vues classiques d’un dessin technique ?', 'mcq', '["De face, de dessus, de gauche","De face seulement","En perspective seulement","De dessous et de droite"]'::jsonb, 0, 'Ensemble, elles décrivent l’objet sans ambiguïté.', 5),
