    ('128e210b-0335-561e-9170-83d7e50e2e93'::uuid, '55d37aeb-f866-5c3c-9b55-0548d8855ef5'::uuid, 'Qu’est-ce qu’un programme ?', 'mcq', '["Une suite d’instructions exécutées dans l’ordre","Un schéma de câblage","Un plan coté","Une liste de matériaux"]'::jsonb, 0, 'Il est téléversé dans la carte.', 1),
    ('43764a94-eb6a-518d-9439-513887208004'::uuid, '55d37aeb-f866-5c3c-9b55-0548d8855ef5'::uuid, 'À quoi sert une boucle ?', 'mcq', '["À répéter des instructions sans les réécrire","À arrêter le programme","À poser une question","À stocker une valeur"]'::jsonb, 0, '« Répéter indéfiniment ».', 2),
    ('eee9b762-0170-5559-bd40-a39cfe14f553'::uuid, '55d37aeb-f866-5c3c-9b55-0548d8855ef5'::uuid, 'Quelle instruction rend un objet capable de réagir ?', 'mcq', '["La condition « si … alors … sinon »","La boucle","La variable","L’instruction simple"]'::jsonb, 0, 'Elle fait dépendre l’action d’un capteur.', 3),
    ('89f9d0f0-7db7-5ca5-b484-60b4b6e65dc6'::uuid, '55d37aeb-f866-5c3c-9b55-0548d8855ef5'::uuid, 'Qu’est-ce qu’une variable ?', 'mcq', '["Une case mémoire nommée qui retient une valeur","Une instruction de répétition","Un capteur","Un actionneur"]'::jsonb, 0, 'Un compteur, une mesure.', 4),
    ('ab951944-7376-581c-b618-b3efcf7f6c40'::uuid, '55d37aeb-f866-5c3c-9b55-0548d8855ef5'::uuid, 'Qu’est-ce qu’un logigramme ?', 'mcq', '["Un schéma des actions et des décisions du programme","Le plan de la carte","La liste des composants","Le code source"]'::jsonb, 0, 'Rectangles pour les actions, losanges pour les décisions.', 5),
    ('3406c40e-9b23-5cfb-89ff-34099fcaae90'::uuid, '55d37aeb-f866-5c3c-9b55-0548d8855ef5'::uuid, 'Que faire quand un programme ne fonctionne pas ?', 'mcq', '["Tester pas à pas et isoler l’instruction fautive","Tout réécrire","Changer de carte","Abandonner"]'::jsonb, 0, 'Un bug est une étape normale.', 6),
    ('bbe3f376-c358-58fb-8028-1c282270a8c7'::uuid, '55d37aeb-f866-5c3c-9b55-0548d8855ef5'::uuid, 'Quelle question pose un objet connecté ?', 'mcq', '["Qui reçoit les données, et pour en faire quoi","Combien il pèse","De quelle couleur il est","Où il est fabriqué"]'::jsonb, 0, 'Sécurité et données personnelles.', 7),
    ('8015a952-6d95-5e9c-ad3b-5b4e0263669c'::uuid, '55d37aeb-f866-5c3c-9b55-0548d8855ef5'::uuid, 'Une machine interprète l’intention du programmeur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle exécute exactement ce qui est écrit.', 8),
    ('3c9f9803-5a27-5509-8ec7-11311b9cfc84'::uuid, '3e987436-78a6-55af-9a2a-24a89581ed30'::uuid, 'Quels sont les deux états du langage binaire ?', 'mcq', '["0 et 1","A et B","Oui et non","+ et −"]'::jsonb, 0, 'Toute information y est convertie.', 1),
    ('06bef1c1-90f4-53e2-91c3-bc3e0ca22098'::uuid, '3e987436-78a6-55af-9a2a-24a89581ed30'::uuid, 'Combien de bits vaut un octet ?', 'mcq', '["8","2","10","16"]'::jsonb, 0, 'Puis viennent ko, Mo, Go, To.', 2),
    ('f6224657-41c1-5dc1-90e0-59acdb8e847b'::uuid, '3e987436-78a6-55af-9a2a-24a89581ed30'::uuid, 'Quel support transporte l’information sous forme de lumière ?', 'mcq', '["La fibre optique","Le câble électrique","Les ondes wifi","Le Bluetooth"]'::jsonb, 0, 'C’est le plus rapide.', 3),
    ('609beca7-74ef-56d6-aff2-8694563ed0d8'::uuid, '3e987436-78a6-55af-9a2a-24a89581ed30'::uuid, 'Comment les données voyagent-elles sur internet ?', 'mcq', '["Découpées en paquets qui empruntent des chemins différents","En un seul bloc continu","Toujours par le même câble","Sans être découpées"]'::jsonb, 0, 'Elles sont réassemblées à l’arrivée.', 4),
    ('eb578af9-188c-55b9-bb87-ef4f6c5ef6a8'::uuid, '3e987436-78a6-55af-9a2a-24a89581ed30'::uuid, 'Qu’est-ce qu’une adresse IP ?', 'mcq', '["L’adresse d’une machine sur un réseau","Un mot de passe","Un type de câble","Une unité de mesure"]'::jsonb, 0, 'Chaque machine connectée en possède une.', 5),
    ('8bc465b6-e5c5-5ada-bc8c-8d789d0366e4'::uuid, '3e987436-78a6-55af-9a2a-24a89581ed30'::uuid, 'Qu’est-ce que le « cloud » ?', 'mcq', '["Des serveurs distants dans un centre de données réel","Une mémoire dans les nuages","Un type de câble","Un logiciel"]'::jsonb, 0, 'Un bâtiment climatisé qui consomme de l’électricité.', 6),
    ('46185176-b1c6-559b-84d0-b0eee65f9f0a'::uuid, '3e987436-78a6-55af-9a2a-24a89581ed30'::uuid, 'Que devient une photo avant d’être transmise ?', 'mcq', '["Elle est convertie en une suite de 0 et de 1","Elle est imprimée","Elle est compressée en papier","Rien, elle circule telle quelle"]'::jsonb, 0, 'Puis reconvertie à l’arrivée.', 7),
    ('da2a5bd5-9916-5b4d-88ce-0769bae8ac90'::uuid, '3e987436-78a6-55af-9a2a-24a89581ed30'::uuid, 'Une donnée publiée en ligne reste sous le contrôle de son auteur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle peut être copiée, conservée et rediffusée à son insu.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('technologie');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('technologie')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 336 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 336 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
